"""Score the task bank and report one number."""
import json

def load(path):
    return [json.loads(line) for line in open(path)]

def run_bank(agent, path="evals/tasks.jsonl"):
    tasks = load(path)
    passed = 0
    for task in tasks:
        result = agent(task["prompt"])
        if result == task["expect"]:
            passed += 1
    # One aggregate. Nothing records how big each task was, so the number
    # cannot be projected onto a longer real task.
    return {"pass_rate": passed / len(tasks), "n": len(tasks)}

