"""Score the task bank and report success as a function of task size."""
import json

HORIZON_BANDS = [(0, 5), (5, 30), (30, 120), (120, 10000)]

def load(path):
    return [json.loads(line) for line in open(path)]

def band_of(human_minutes):
    for low, high in HORIZON_BANDS:
        if low <= human_minutes < high:
            return "%d-%dmin" % (low, high)
    return "unbanded"

def run_bank(agent, path="evals/tasks.jsonl"):
    tasks = load(path)
    # Every task carries a human_minutes label, so the score is reported
    # stratified by horizon band and never collapsed to one mean.
    by_band = {}
    for task in tasks:
        band = band_of(task["human_minutes"])
        ok = agent(task["prompt"]) == task["expect"]
        hit, total = by_band.get(band, (0, 0))
        by_band[band] = (hit + int(ok), total + 1)
    return {band: hit / total for band, (hit, total) in by_band.items()}
